  procedure('utility:VanillaTwoHandedAnimation',(c,r,t,w)=>{const a=__utilityArm(c),b=__utilityOther(a);r.rotate(__utilityUpper(a),-30*w,(a==='right'?-8:8)*w,0);r.rotate(__utilityElbow(a),-28*w,0,0);r.rotate(__utilityUpper(b),-32*w,(b==='right'?-18:18)*w,0);r.rotate(__utilityElbow(b),-48*w,0,0);return true;});
  procedure('utility:ItemSwapAnimation',(c,r,t,w)=>{const s=__utilityArm(c),p=clamp(t/.5,0,1),a=Math.sin(p*Math.PI);r.rotate(__utilityUpper(s),-28*a*w,0,(s==='right'?-38:38)*a*w);return true;});
