  procedure('utility:SleepAnimation',(c,r,t,w)=>{r.rotate(playerRig.bone('left_upper_arm'),0,0,-8*w);r.rotate(playerRig.bone('right_upper_arm'),0,0,8*w);r.rotate(playerRig.bone('left_knee'),-8*w,0,0);r.rotate(playerRig.bone('right_knee'),-8*w,0,0);return true;});
  procedure('utility:MapHoldingAnimation',(c,r,t,w)=>{const pitch=clamp(c.headPitch,-70,70);r.rotate(playerRig.bone('left_upper_arm'),(-55-pitch*.2)*w,-18*w,-8*w);r.rotate(playerRig.bone('right_upper_arm'),(-55-pitch*.2)*w,18*w,8*w);r.rotate(playerRig.bone('left_elbow'),-46*w,8*w,0);r.rotate(playerRig.bone('right_elbow'),-46*w,-8*w,0);return true;});
  procedure('utility:BoatAnimation',(c,r,t,w)=>{__utilityPlay('motion:boat_idle',c,r,t,w);if(c.boatLeft&&c.boatRight)__utilityPlay('motion:boat_forward',c,r,(c.boatLeftTime+c.boatRightTime)/(Math.PI*2),w);else if(c.boatLeft)__utilityPlay('motion:boat_left_paddle',c,r,c.boatLeftTime/Math.PI,w);else if(c.boatRight)__utilityPlay('motion:boat_right_paddle',c,r,c.boatRightTime/Math.PI,w);return true;});
