  procedure('utility:RiptideAnimation',(c,r,t,w)=>{for(const s of ['left','right']){const sign=s==='right'?1:-1;r.rotate(__utilityUpper(s),-164*w,sign*5*w,sign*3*w);r.rotate(__utilityElbow(s),-8*w,0,0);}r.rotate(playerRig.bone('chest'),-12*w,0,0);return true;});
