  procedure('utility:NarutoRunningAnimation',(c,r,t,w)=>{r.rotate(playerRig.bone('left_upper_arm'),52*w,0,-8*w);r.rotate(playerRig.bone('right_upper_arm'),52*w,0,8*w);r.rotate(playerRig.bone('left_elbow'),-8*w,0,0);r.rotate(playerRig.bone('right_elbow'),-8*w,0,0);return true;});
