  procedure('utility:VanillaProjectileWeaponAnimation',(c,r,t,w)=>{if(c.useItem.includes('bow'))return __utilityPlay('motion:use_bow',c,r,c.useTimeSeconds,w);if(c.useItem.includes('crossbow'))return __utilityPlay('motion:hold_crossbow',c,r,c.useTimeSeconds,w);return __utilityPlay('motion:hold_spear',c,r,c.useTimeSeconds,w);});


  const mirrorPairs=new Map();
  const pair=(a,b)=>{a=playerRig.bone(a);b=playerRig.bone(b);if(a>=0&&b>=0){mirrorPairs.set(a,b);mirrorPairs.set(b,a);}};
